# Hemp living positioning. Proposed facilities are explicitly marked as planned.
nav=[('stay','Stay'),('experience','Experience Hemp'),('hemp','Build With Hemp'),('retreats','Workshops & Retreats'),('story','Our Story'),('visit','Before You Come'),('gallery','Gallery')]
def enquiry_link(message,label):return link(enquire(message),label)
segments='''<section class="hemp-paths wrap" id="choose-experience"><div class="section-heading"><div><p class="eyebrow">THREE WAYS TO BELONG</p><h2>Come curious.<br>Stay your own way.</h2></div><p>A quiet home for travellers,<br>future builders and hands-on learners.</p></div><div class="hemp-path-grid"><article><span class="eyebrow">01 · PROSPECTIVE BUILDERS</span><h3>Live Before<br>You Build.</h3><p>A 2–3 night trial stay to experience hempcrete rooms, notice their everyday comfort and discuss the questions behind your own project.</p><a class="text-link" href="/hemp/#builder-stay">Explore the builder stay →</a></article><article><span class="eyebrow">02 · ECO-TRAVELLERS</span><h3>Stay Close<br>to Nature.</h3><p>Slow mornings, mountain light and a home made with natural materials. Discover the hemp story at your own pace; activities are optional.</p><a class="text-link" href="/stay/">Find your quiet stay →</a></article><article><span class="eyebrow">03 · RESEARCHERS &amp; LEARNERS</span><h3>Learn<br>With Hemp.</h3><p>Discuss a focused learning visit, workshop or residency around hemp materials, natural building and the journey from plant to everyday use.</p><a class="text-link" href="/retreats/#learning">Explore learning visits →</a></article></div></section>'''
vision='''<section class="hemp-vision wrap"><div><p class="eyebrow">FROM PLANT TO PLACE</p><h2>A home today.<br>A living showcase<br>taking shape.</h2><p>Our ancestral property brings hemp-based architecture and Himalayan village life together. We are developing an integrated hemp farm and immersive living experience around the home.</p><a class="text-link" href="/experience/">Discover the next chapter →</a></div><div class="hemp-stages"><article><span class="stage-label">EXPERIENCE TODAY</span><h3>Live within the material</h3><p>Stay in genuine hempcrete rooms and explore the house’s natural finishes with the hosts, by arrangement.</p></article><article><span class="stage-label">PLANNED · SEASONAL</span><h3>A small cultivation patch</h3><p>We plan to grow a small on-site patch under our cultivation licence. Hosted field walks will depend on planting, the season and visitor access being ready.</p></article><article><span class="stage-label">PLANNED</span><h3>Hemp Experience Center</h3><p>A dedicated room for raw materials, wall-section samples, construction stories and finished goods. Opening details will be shared when the space is ready.</p></article></div></section>'''
home=pages[''][1]
home=home.replace('Stay a while.<br>Come back to <em>calm.</em>','A Hemp Home.<br>A Living <em>Experience.</em>').replace('AN UNHURRIED HIMALAYAN STAY','STAY · DISCOVER · LEARN').replace('A hemp home in the Himalayas.<br>For slow mornings, quiet days and longer stays.','Come for the calm. Discover the material.<br>Experience another way of living.').replace('href="/house/">Explore the house','href="/experience/">Experience hemp')
home=home.replace('Welcome to a village home in the hills of Uttarakhand, where natural materials, thoughtful spaces and a slower rhythm make room for what matters.','Welcome to an ancestral hemp home in Uttarakhand. Stay within the material, meet the ideas behind the walls, and discover a slower rhythm rooted in village life.')
home=home.replace('<section class="editorial wrap">',segments+'<section class="editorial wrap">').replace('<section class="arrival wrap">',vision+'<section class="arrival wrap">')
